-- Remove synthetic/fabricated deals from the deals table
-- These were generated by AI and contain fake company names or future dates
-- Only real, publicly announced deals should remain

-- 1. Remove deals with fabricated company names
DELETE FROM deals WHERE licensor_name IN (
  'MetaboGen Therapeutics', 'IncretaPharm', 'LiverAxis Biosciences',
  'GutBiome Pharma', 'OralPeptide Sciences', 'AmylinTech',
  'SGLT Sciences', 'RareMeta Therapeutics', 'LipoCure Biotech',
  'PKU Genetics', 'LipoThera Inc', 'ActivinBio',
  'CardioMeta Sciences', 'ImplantRx', 'Earendil Labs',
  'Metsera', 'Vasa Therapeutics', 'TurnBiotechnologies',
  'Proteologics', 'FutureGen Biopharmaceutical',
  'Shanghai Argo Biopharmaceutical', 'Argo Biopharma',
  'Modifi Biosciences', 'GRIN Therapeutics', 'UgeneX Therapeutics',
  'Iolyx Therapeutics'
);

-- Also remove deals where licensee is fabricated
DELETE FROM deals WHERE licensee_name IN (
  'Empirico', 'Undisclosed Pharma'
);

-- 2. Remove future-dated deals (announced after today = speculative)
DELETE FROM deals WHERE announced_date > CURRENT_DATE;

-- 3. Log the cleanup
DO $$
DECLARE
  remaining_count INTEGER;
BEGIN
  SELECT COUNT(*) INTO remaining_count FROM deals;
  RAISE NOTICE 'Synthetic deal cleanup complete. % deals remaining.', remaining_count;
END $$;
